import { loadEnvFileIfPresent } from '@mercato/config';
import pg from 'pg';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';

/**
 * Applies SQL migrations from src/db/migrations (generated by
 * `pnpm db:generate`) using the migration credentials. Intentionally separate
 * from the runtime role: the application role must not own DDL
 * (see docs/operations/database-migrations.md).
 */
async function runMigrations(): Promise<void> {
  loadEnvFileIfPresent();
  const url = process.env['DATABASE_MIGRATION_URL'] ?? process.env['DATABASE_URL'];
  if (url === undefined || url === '') {
    console.error('[mercato] DATABASE_URL (or DATABASE_MIGRATION_URL) must be set');
    process.exitCode = 1;
    return;
  }

  const pool = new pg.Pool({ connectionString: url, max: 1, application_name: 'mercato-migrate' });
  try {
    const db = drizzle(pool);
    await migrate(db, { migrationsFolder: 'src/db/migrations' });
    console.log('[mercato] migrations applied');
  } finally {
    await pool.end();
  }
}

runMigrations().catch((error: unknown) => {
  console.error('[mercato] migration failed:', error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
